#!/usr/bin/perl

# Derived from PeaksAndGenes script generated by Kathryn Ramsey in February, 2015
# USAGE: ./PeaksAndGenes_Ab_macs3.pl InputFile_AllPeaks.tsv
## Updated Apr 12, 2023 to be compatible with A. baumannii AB0575 genome files.
## Updated in 2026 for use with MACS3 output of narrowPeaks file format 
use strict;
use warnings;

#BEFORE RUNNING!!! ensure .narrowPeaks has line numbers try running something like this perl -ne 'print "$. $_"' FILE.narrowPeak > NEWFILE.narrowPeak to add those

#For each ORF, we need to find the locus number from the .gff file (including tRNAs and rRNAs, which don't have locus numbers but can be identified by rna#. Specifically, the rRNA or tRNA line will indicate "ID=rna#" in the 9th column).

my ($peakfile, $outfile);

$peakfile = shift @ARGV;
  unless ($peakfile =~ /\.narrowPeak$/) {
  die "PeaksAndGenes_Ab_macs3.pl - INPUT ERROR! #Please use a .tsv file.\n";
}

if ($peakfile =~ /(\S*)\.narrowPeak/) {
  $outfile = $1."_Genes.tsv";
}
else { die "Error! I didn't recognize the input well enough to define an output file name. The input file should be from the MergePeaks program and should end in \"_AllPeaks.tsv\": $!\n";}

open PEAKS, $peakfile or die "Could not open '$peakfile': $!\n";


#Hashes: peak number is key, want average max position, start, end, and enrichment factor
my (@line, %Maxpos, %Pstart, %Pend, %Enrich, %Psize, %peakchrom);
while (<PEAKS>) {
  chomp;
#unless (/^\d+/) {next;}
  @line = split;
  $peakchrom{$line[0]} = $line[1];
  $Maxpos{$line[0]} = ($line[2] + $line[10]);
  #print "%Maxpos\n";
  $Pstart{$line[0]} = $line[2];
  $Pend{$line[0]} = $line[3];
  $Enrich{$line[0]} = $line[7];
  $Psize{$line[0]} = ($line[3] - $line[2]);
}

close PEAKS;


my @peaks = sort { $a <=> $b } keys %Maxpos;


###Open the gff files for chromosomes and find genes within 1000 bps of each peak

open OUT, ">$outfile" or die "Could not open $outfile: $!\n";
print OUT "Peak Number\tEnrichment Factor\tChromosome\tMax Position\tStart\tEnd\tSize\tGene Locus\tDistance\tStrand\tGene Name\tGene Product\tCOG\n";

my ($currentpeak, @gline, @productline, @rnaline, $gstart, $strand, $pMax, $dis, $locus, $gname, $gproduct, $COG);

foreach $currentpeak (@peaks) {
  $pMax = $Maxpos{"$currentpeak"};
  # chromosome block
  if ($peakchrom{"$currentpeak"} eq "AB5075UW") {
    open GENEFILE1, 'AB5075UW.gff' or die "Cannot open AB5075UW.gff. Did you check that it's present in the same folder as this program? $!\n";
    while (<GENEFILE1>) {
      chomp;
      @gline = 0;      
      @productline = 0;      
#      $gstart=();
      unless (/^AB5075UW\t\w+\tgene/) {next;} 
	  @gline = split(' ',$_,9);
      if ($gline[6] eq "+") {
	    $gstart = $gline[3] - 1;
	    $strand = 0;
      }
      elsif ($gline[6] eq "-") {
	    $gstart = $gline[4] - 1;
	    $strand = 1;
      }
      if (abs($pMax-$gstart)<=1000) {
	if ($strand == 0) {
	  $dis = ($pMax - $gstart);
	}
	elsif ($strand == 1) {
	  $dis = ($gstart - $pMax);
	}
	if ($gline[8] =~ /locus_tag=(ABUW_\d{4})/) { # normal coding gene
	  $locus = $1;
	  open PRODUCTFILE1, 'AB5075UW.ptt' or die "Cannot open AB5075UW.ptt file. Did you check that it's present in the correct path?\n";
	  while (<PRODUCTFILE1>) {
	    unless (/$locus/) {next;}
	    chomp;
	    @productline = split ("\t");
#	    print "This is the product line: @productline\n";
	    $gname = $productline[4];
	    $gproduct = $productline[8];
	    $COG = $productline[7];
	  }
	  close PRODUCTFILE1;
	}
	elsif ($gline[8] =~ /locus_tag=(ABUWs\d{3})/) { # sRNA gene
	  $locus = $1;  
	  $gname = "-";
	  $gproduct = "putative sRNA";
	  $COG = "-";
	}
      my $max = $Maxpos{$currentpeak}+1 ; my $start = $Pstart{$currentpeak}+1; my $end = $Pend{$currentpeak}+1;$dis=-$dis;
	print OUT "$currentpeak\t".$Enrich{$currentpeak}."\t".$peakchrom{$currentpeak}."\t$max\t$start\t$end\t".$Psize{$currentpeak}."\t$locus\t$dis\t$gline[6]\t$gname\t$gproduct\t$COG\n";
      $gname = "";
      $gproduct = "";
      $COG = "";
      $locus = "";
      }
      else {
	$dis = ();
	next;}
    }
  }
  #plasmid 1 block
  if ($peakchrom{"$currentpeak"} eq "p1AB5075") {
    open GENEFILE2, 'p1AB5075.gff' or die "Cannot open p1AB5075.gff. Did you check that it's present in the same folder as this program? $!\n";
    while (<GENEFILE2>) { ##### Note that there are no rRNAs encoded in this chromosome, but there are tRNAs
      chomp;
      @gline = 0;      
      @productline = 0;      
 #     $gstart = ();
      unless (/^p1AB5075\t\w+\tgene/) {next;} 
	  @gline = split(' ',$_,9);
      $locus = ();
      if ($gline[6] eq "+") {
	$gstart = $gline[3] - 1;
	$strand = 0;
      }
      elsif ($gline[6] eq "-") {
	$gstart = $gline[4] - 1;
	$strand = 1;
      }
      if (abs($pMax-$gstart)<=1000) {
	if ($strand == 0) {
	  $dis = ($pMax - $gstart);
	}
	elsif ($strand == 1) {
	  $dis = ($gstart - $pMax);
	}
#	print "$gline[8]\n";
	if ($gline[8] =~ /locus_tag=(ABUW_\d{4})/) {  ##If the gene is a normal protein-coding gene
	  $locus = $1;
	  open PRODUCTFILE2, 'p1AB5075.ptt' or die "Cannot open p1AB5075.ptt file. Did you check that it's present in the correct path?\n";
	  while (<PRODUCTFILE2>) {
	    unless (/$locus/) {next;}
	    chomp;
	    @productline = split ("\t");
#	    print "This is the product line: @productline\n";
	    $gname = $productline[4];
	    $gproduct = $productline[8];
	    $COG = $productline[7];
	  }
	  close PRODUCTFILE2;
	}
	elsif ($gline[8] =~ /locus_tag=(ABUWs\d{3})/) { ##If the ORF encodes an sRNA
	  $locus = $1;  
	  $gname = "-";
	  $gproduct = "putative sRNA";
	  $COG = "-";
	}

      my $max = $Maxpos{$currentpeak}+1 ; my $start = $Pstart{$currentpeak}+1; my $end = $Pend{$currentpeak}+1;$dis=-$dis;
	print OUT "$currentpeak\t".$Enrich{$currentpeak}."\t".$peakchrom{$currentpeak}."\t$max\t$start\t$end\t".$Psize{$currentpeak}."\t$locus\t$dis\t$gline[6]\t$gname\t$gproduct\t$COG\n";
            $gname = "";
      $gproduct = "";
      $COG = "";
      $locus = "";
      }
      else {
	$dis = ();
	next;}
    }
  }
#plasmid 2 block
    if ($peakchrom{"$currentpeak"} eq "p2AB5075") {
    open GENEFILE3, 'p2AB5075.gff' or die "Cannot open p2AB5075.gff. Did you check that it's present in the same folder as this program? $!\n";
    while (<GENEFILE3>) { ##### Note that there are no rRNAs encoded in this chromosome, but there are tRNAs
      chomp;
      @gline = 0;     
       @productline = 0;      
 #      $gstart = ();
      unless (/^p2AB5075\t\w+\tgene/) {next;} 
	  @gline = split(' ',$_,9);
      $locus = ();
      if ($gline[6] eq "+") {
	$gstart = $gline[3] - 1;
	$strand = 0;
      }
      elsif ($gline[6] eq "-") {
	$gstart = $gline[4] - 1;
	$strand = 1;
      }
      if (abs($pMax-$gstart)<=1000) {
	if ($strand == 0) {
	  $dis = ($pMax - $gstart);
	}
	elsif ($strand == 1) {
	  $dis = ($gstart - $pMax);
	}
#	print "$gline[8]\n";
	if ($gline[8] =~ /locus_tag=(ABUW_\d+|ABUWs\d+)/) {  ##If the gene is a normal protein-coding gene
	  $locus = $1;
	  open PRODUCTFILE3, 'p2AB5075.ptt' or die "Cannot open p2AB5075.ptt file. Did you check that it's present in the correct path?\n";
	  while (<PRODUCTFILE3>) {
	    unless (/$locus/) {next;}
	    chomp;
	    @productline = split ("\t");
#	    print "This is the product line: @productline\n";
	    $gname = $productline[4];
	    $gproduct = $productline[8];
	    $COG = $productline[7];
	  }
	  close PRODUCTFILE3;
	}
	elsif ($gline[8] =~ /locus_tag=(ABUW_\d+|ABUWs\d+)/) {   ##If the ORF encodes a tRNA or rRNA
	  $locus = $1;  
	  $gname = /;Name=(\w*);/;
	  $gproduct = /;gene=(\w*);/;
	  $COG = "-";
	}
      my $max = $Maxpos{$currentpeak}+1 ; my $start = $Pstart{$currentpeak}+1; my $end = $Pend{$currentpeak}+1;$dis=-$dis;
	print OUT "$currentpeak\t".$Enrich{$currentpeak}."\t".$peakchrom{$currentpeak}."\t$max\t$start\t$end\t".$Psize{$currentpeak}."\t$locus\t$dis\t$gline[6]\t$gname\t$gproduct\t$COG\n";
      $gname = "";
      $gproduct = "";
      $COG = "";
      $locus = "";
      }
      else {
	$dis = ();
	next;}
    }
  }
#plasmid 3 block  
    if ($peakchrom{"$currentpeak"} eq "p3AB5075") {
    open GENEFILE4, 'p3AB5075.gff' or die "Cannot open p3AB5075.gff. Did you check that it's present in the same folder as this program? $!\n";
    while (<GENEFILE4>) { ##### Note that there are no rRNAs encoded in this chromosome, but there are tRNAs
      chomp;
      @gline = 0;      
      @productline = 0;      
 #     $gstart = ();
      unless (/^p3AB5075\t\w+\tgene/) {next;} 
	  @gline = split(' ',$_,9);
      $locus = ();
      if ($gline[6] eq "+") {
	$gstart = $gline[3] - 1;
	$strand = 0;
      }
      elsif ($gline[6] eq "-") {
	$gstart = $gline[4] - 1;
	$strand = 1;
      }
      if (abs($pMax-$gstart)<=1000) {
	if ($strand == 0) {
	  $dis = ($pMax - $gstart);
	}
	elsif ($strand == 1) {
	  $dis = ($gstart - $pMax);
	}
#	print "$gline[8]\n";
	if ($gline[8] =~ /locus_tag=(ABUW_\d+|ABUWs\d+)/) {  ##If the gene is a normal protein-coding gene
	  $locus = $1;
	  open PRODUCTFILE4, 'p3AB5075.ptt' or die "Cannot open p3AB5075.ptt file. Did you check that it's present in the correct path?\n";
	  while (<PRODUCTFILE4>) {
	    unless (/$locus/) {next;}
	    chomp;
	    @productline = split ("\t");
#	    print "This is the product line: @productline\n";
	    $gname = $productline[4];
	    $gproduct = $productline[8];
	    $COG = $productline[7];
	  }
	  close PRODUCTFILE4;
	}
	elsif ($gline[8] =~ /locus_tag=(ABUW_\d+|ABUWs\d+)/) {   ##If the ORF encodes a tRNA or rRNA
	  $locus = $1;  
	  $gname = /;Name=(\w*);/;
	  $gproduct = /;gene=(\w*);/;
	  $COG = "-";
	}
      my $max = $Maxpos{$currentpeak}+1 ; my $start = $Pstart{$currentpeak}+1; my $end = $Pend{$currentpeak}+1;$dis=-$dis;
	print OUT "$currentpeak\t".$Enrich{$currentpeak}."\t".$peakchrom{$currentpeak}."\t$max\t$start\t$end\t".$Psize{$currentpeak}."\t$locus\t$dis\t$gline[6]\t$gname\t$gproduct\t$COG\n";
      $gname = "";
      $gproduct = "";
      $COG = "";
      $locus = "";
    }
      else {next;}
    }
  }
}
close GENEFILE1; close GENEFILE2; close GENEFILE3; close GENEFILE4; close OUT;






